@router.delete("/analytics/saved-queries/{query_id}")
async def delete_saved_query(
    query_id: int,
    current_user: User = Depends(get_current_user)
):
    saved_query = await SavedReportQuery.objects.get_or_none(
        id=query_id,
        author_id=current_user.id
    )
    if not saved_query:
        raise HTTPException(status_code=404, detail="Saved query not found or access denied")
    await saved_query.delete()
    return {"deleted": True, "query_id": query_id}
